parts=['<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="510" viewBox="0 0 1000 510" role="img" aria-labelledby="title desc">','<title id="title">Independent AI issue screening outcomes</title>','<desc id="desc">Screening opinions for 52 issues. No task success is measured.</desc>','<rect width="1000" height="510" fill="#f7f8fa"/>','<text x="58" y="52" font-family="Arial, sans-serif" font-size="28" font-weight="700" fill="#142b3a">AI candidate screening · not task outcomes</text>','<text x="58" y="86" font-family="Arial, sans-serif" font-size="16" fill="#526a78">52 public issues · two independent model calls per issue</text>']
