 y=132+i*56;parts.append(f'<text x="58" y="{y+24}" font-family="Arial, sans-serif" font-size="17" fill="#142b3a">{label}</text>');parts.append(f'<rect x="315" y="{y}" width="{value*22}" height="34" rx="4" fill="{color}"/>');parts.append(f'<text x="{325+value*22}" y="{y+24}" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#142b3a">{value}</text>')
